"""Run momentum v3 for one date and publish it. Generated by `asof export`.

    python run.py --as-of 2026-09-15          # price one day
    python run.py                             # today, in the calendar of asof.toml

Data is read from ./data/<input>.csv (mount or sync it there). Output goes to
the sink declared in asof.toml. Exit code is non-zero on any failure, so a
scheduler can alert on it.
"""
from __future__ import annotations

import argparse
import sys
from datetime import date
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))  # the signal module lives next to this file

from asof import registry, run  # noqa: E402
from asof.config import load_config  # noqa: E402
from asof.sink import publish, rows_from_output  # noqa: E402


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--as-of", default=date.today().isoformat())
    parser.add_argument("--data", default=str(HERE / "data"))
    args = parser.parse_args()
    as_of = date.fromisoformat(args.as_of)

    config = load_config(HERE / "asof.toml")
    if as_of not in config.calendar.dates(as_of, as_of):
        print(f"{as_of} is not a pricing day in this calendar; nothing to do")
        return 0
    model = registry.load_file(HERE / "momentum.py")["momentum"]
    result = run(model, as_of, data_dir=args.data)
    rows = rows_from_output(result.output, as_of=as_of, model="momentum", version=3,
                            fingerprint="34ab44949483f1c9")
    print(publish(rows, config.sink, root=HERE))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
